window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-861078296617820a"]={"versions": [{"id": "FIG-861078296617820a", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Default Error Tracer (Det) innerhalb der AUTOSAR Classic Platform-Basissoftware. Es modelliert den Kontrollfluss beim Melden eines transienten Fehlers (<code>Det_ReportTransientFault</code>), wenn im Det keine anwenderspezifischen Callout-Hooks konfiguriert sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Det User</strong>: Software-Komponente oder BSW-Modul, das einen transienten Fehler feststellt und meldet.\n</li><li><strong>Det</strong> (<code>«module»</code>): Das zentrale AUTOSAR-Basissoftwaremodul Default Error Tracer zur Erfassung von Fehlermeldungen.\n</li><li><strong>Integrator Code</strong>: Vorgesehener Empfänger für anwenderspezifische Callout-Routinen (als passive Lebenslinie dargestellt, da in diesem Szenario nicht adressiert).\n</li><li><strong>Schnittstelle</strong>:\n<ul class=\"fig-list\"><li><code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code>: Synchroner Funktionsaufruf zur Fehlermeldung mit Identifikatoren für Modul, Instanz, API und Fehlertyp.\n</li><li><code>:E_OK</code>: Rückgabewert des Funktionsaufrufs an den Aufrufer.\n</li></ul>\n</li><li><strong>Konfigurationskontext</strong>: Notiz <code>&lt;Det_General&gt; TransientFault callouts NOT configured</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Det User</code> initiiert den synchronen Aufruf <code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code> an das Modul <code>Det</code>.\n</li><li>Auf der Det-Lebenslinie wird die Ausführung aktiviert. Da gemäß Notiz <code>&lt;Det_General&gt;</code> keine TransientFault-Callouts konfiguriert sind, erfolgt keine Interaktion mit dem <code>Integrator Code</code>.\n</li><li><code>Det</code> beendet die Ausführung und liefert unmittelbar den Statuswert <code>E_OK</code> synchron an den <code>Det User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zeigt das Standard-Fall-Through-Verhalten der Funktion <code>Det_ReportTransientFault</code> bei unkonfigurierten Hooks: Ohne registrierte Callouts erzeugt der Aufruf keine Weiterleitung an Integrator-Routinen, blockiert nicht und quittiert die Meldung erfolgreich mit <code>E_OK</code>. Entwickler und Integratoren müssen beachten, dass das Ausbleiben einer Callout-Konfiguration die Fehlerbehandlung auf die modulinterne Quittierung beschränkt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ee5eb375a0373b97", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Default Error Tracer (Det) innerhalb der AUTOSAR Classic Platform-Basissoftware. Es modelliert den Kontrollfluss beim Melden eines transienten Fehlers (<code>Det_ReportTransientFault</code>), wenn im Det keine anwenderspezifischen Callout-Hooks konfiguriert sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Det User</strong>: Software-Komponente oder BSW-Modul, das einen transienten Fehler feststellt und meldet.\n</li><li><strong>Det</strong> (<code>«module»</code>): Das zentrale AUTOSAR-Basissoftwaremodul Default Error Tracer zur Erfassung von Fehlermeldungen.\n</li><li><strong>Integrator Code</strong>: Vorgesehener Empfänger für anwenderspezifische Callout-Routinen (als passive Lebenslinie dargestellt, da in diesem Szenario nicht adressiert).\n</li><li><strong>Schnittstelle</strong>:\n<ul class=\"fig-list\"><li><code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code>: Synchroner Funktionsaufruf zur Fehlermeldung mit Identifikatoren für Modul, Instanz, API und Fehlertyp.\n</li><li><code>:E_OK</code>: Rückgabewert des Funktionsaufrufs an den Aufrufer.\n</li></ul>\n</li><li><strong>Konfigurationskontext</strong>: Notiz <code>&lt;Det_Notification&gt; TransientFault callouts NOT configured</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Det User</code> initiiert den synchronen Aufruf <code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code> an das Modul <code>Det</code>.\n</li><li>Auf der Det-Lebenslinie wird die Ausführung aktiviert. Da gemäß Notiz <code>&lt;Det_Notification&gt;</code> keine TransientFault-Callouts konfiguriert sind, erfolgt keine Interaktion mit dem <code>Integrator Code</code>.\n</li><li><code>Det</code> beendet die Ausführung und liefert unmittelbar den Statuswert <code>E_OK</code> synchron an den <code>Det User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zeigt das Standard-Fall-Through-Verhalten der Funktion <code>Det_ReportTransientFault</code> bei unkonfigurierten Hooks: Ohne registrierte Callouts erzeugt der Aufruf keine Weiterleitung an Integrator-Routinen, blockiert nicht und quittiert die Meldung erfolgreich mit <code>E_OK</code>. Entwickler und Integratoren müssen beachten, dass das Ausbleiben einer Callout-Konfiguration die Fehlerbehandlung auf die modulinterne Quittierung beschränkt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1a2dd36b22949c12", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Default Error Tracer (Det) innerhalb der AUTOSAR Classic Platform-Basissoftware. Es modelliert den Kontrollfluss beim Melden eines transienten Fehlers (<code>Det_ReportTransientFault</code>), wenn im Det keine anwenderspezifischen Callout-Hooks konfiguriert sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Det User</strong>: Software-Komponente oder BSW-Modul, das einen transienten Fehler feststellt und meldet.\n</li><li><strong>Det</strong> (<code>«module»</code>): Das zentrale AUTOSAR-Basissoftwaremodul Default Error Tracer zur Erfassung von Fehlermeldungen.\n</li><li><strong>Integrator Code</strong>: Vorgesehener Empfänger für anwenderspezifische Callout-Routinen (als passive Lebenslinie dargestellt, da in diesem Szenario nicht adressiert).\n</li><li><strong>Schnittstelle</strong>:\n<ul class=\"fig-list\"><li><code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code>: Synchroner Funktionsaufruf zur Fehlermeldung mit Identifikatoren für Modul, Instanz, API und Fehlertyp.\n</li><li><code>:E_OK</code>: Rückgabewert des Funktionsaufrufs an den Aufrufer.\n</li></ul>\n</li><li><strong>Konfigurationskontext</strong>: Notiz <code>&lt;Det_Notification&gt; TransientFault callouts NOT configured</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Det User</code> initiiert den synchronen Aufruf <code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code> an das Modul <code>Det</code>.\n</li><li>Auf der Det-Lebenslinie wird die Ausführung aktiviert. Da gemäß Notiz <code>&lt;Det_Notification&gt;</code> keine TransientFault-Callouts konfiguriert sind, erfolgt keine Interaktion mit dem <code>Integrator Code</code>.\n</li><li><code>Det</code> beendet die Ausführung und liefert unmittelbar den Statuswert <code>E_OK</code> synchron an den <code>Det User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zeigt das Standard-Fall-Through-Verhalten der Funktion <code>Det_ReportTransientFault</code> bei unkonfigurierten Hooks: Ohne registrierte Callouts erzeugt der Aufruf keine Weiterleitung an Integrator-Routinen, blockiert nicht und quittiert die Meldung erfolgreich mit <code>E_OK</code>. Entwickler und Integratoren müssen beachten, dass das Ausbleiben einer Callout-Konfiguration die Fehlerbehandlung auf die modulinterne Quittierung beschränkt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-861078296617820a", "to": "FIG-ee5eb375a0373b97", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Kommentarbox an der Det-Lebenslinie: Die Konfigurationscontainer-Referenz in der Notiz wurde von <code>&lt;Det_General&gt;</code> zu <code>&lt;Det_Notification&gt;</code> korrigiert.\n</li></ul>"}, {"from": "FIG-ee5eb375a0373b97", "to": "FIG-1a2dd36b22949c12", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
